    {
      "source_url": "https://x.com/lookner/status/2083703751404028286",
      "text": "Suspected shooter in Idaho In-N-Out shooting is dead, police are working on identifying him and figuring out the motivation\n\n(from press conference)",
      "author_handle": "lookner",
